+package com.example.ecommerce;

+import android.content.Intent;
+import android.os.Bundle;
+import android.text.TextUtils;
+import android.view.View;
+import android.widget.Button;
+import android.widget.ImageView;
+import android.widget.RatingBar;
+import android.widget.TextView;
+import android.widget.Toast;
+
+import androidx.appcompat.app.AlertDialog;
+import androidx.appcompat.app.AppCompatActivity;
+
+import com.bumptech.glide.Glide;
+import com.google.android.material.appbar.MaterialToolbar;
+import com.google.android.material.textfield.TextInputEditText;
+import com.google.firebase.auth.FirebaseAuth;
+import com.google.firebase.auth.FirebaseUser;
+
+import java.text.NumberFormat;
+import java.util.Locale;
+
+import models.Product;
+import models.Review;
+import repository.FirebaseRepository;
+import repository.ReviewRepository;
+
+public class ProductReviewActivity extends AppCompatActivity {
+
+ private MaterialToolbar toolbar;
+ private ImageView imgProduct;
+ private TextView tvProductName, tvOrderId, tvProductPrice;
+ private RatingBar ratingBar;
+ private TextInputEditText etComment;
+ private Button btnSubmitReview;
+
+ private String productId, orderId;
+ private Product product;
+ private FirebaseUser currentUser;
+ private ReviewRepository reviewRepository;
+ private FirebaseRepository firebaseRepository;
+ private AlertDialog progressDialog;
+
+ @Override
+ protected void onCreate(Bundle savedInstanceState) {
+ super.onCreate(savedInstanceState);
+ setContentView(R.layout.activity_product_review);
+
+ // Initialize Firebase
+ currentUser = FirebaseAuth.getInstance().getCurrentUser();
+ if (currentUser == null) {
+ Toast.makeText(this, "Bạn cần đăng nhập để đánh giá sản phẩm", Toast.LENGTH_SHORT).show();
+ finish();
+ return;
+ }
+
+ // Get product ID and order ID from intent
+ productId = getIntent().getStringExtra("PRODUCT_ID");
+ orderId = getIntent().getStringExtra("ORDER_ID");
+
+ if (productId == null || orderId == null) {
+ Toast.makeText(this, "Không tìm thấy thông tin sản phẩm", Toast.LENGTH_SHORT).show();
+ finish();
+ return;
+ }
+
+ // Initialize repositories
+ reviewRepository = new ReviewRepository();
+ firebaseRepository = new FirebaseRepository();
+
+ // Initialize views
+ initViews();
+ setupToolbar();
+
+ // Load product details
+ loadProductDetails();
+
+ // Setup submit button
+ btnSubmitReview.setOnClickListener(v -> validateAndSubmitReview());
+ }
+
+ private void initViews() {
+ toolbar = findViewById(R.id.toolbar);
+ imgProduct = findViewById(R.id.imgProduct);
+ tvProductName = findViewById(R.id.tvProductName);
+ tvOrderId = findViewById(R.id.tvOrderId);
+ tvProductPrice = findViewById(R.id.tvProductPrice);
+ ratingBar = findViewById(R.id.ratingBar);
+ etComment = findViewById(R.id.etComment);
+ btnSubmitReview = findViewById(R.id.btnSubmitReview);
+ }
+
+ private void setupToolbar() {
+ toolbar.setNavigationOnClickListener(v -> onBackPressed());
+ }
+
+ private void loadProductDetails() {
+ // Show progress dialog
+ showProgressDialog();
+
+ // Load product details
+ firebaseRepository.getProductById(productId, new FirebaseRepository.ProductCallback() {
+ @Override
+ public void onCallback(Product productData) {
+ hideProgressDialog();
+ product = productData;
+ displayProductDetails();
+ }
+
+ @Override
+ public void onError(String errorMessage) {
+ hideProgressDialog();
+ Toast.makeText(ProductReviewActivity.this,
+ "Lỗi khi tải thông tin sản phẩm: " + errorMessage, Toast.LENGTH_SHORT).show();
+ finish();
+ }
+ });
+ }
+
+ private void displayProductDetails() {
+ if (product == null) return;
+
+ // Display product image
+ if (product.getImageUrl() != null && !product.getImageUrl().isEmpty()) {
+ Glide.with(this)
+ .load(product.getImageUrl())
+ .placeholder(R.drawable.placeholder_image)
+ .error(R.drawable.error_image)
+ .into(imgProduct);
+ }
+
+ // Display product name
+ tvProductName.setText(product.getName());
+
+ // Display order ID
+ tvOrderId.setText("Đơn hàng #" + orderId);
+
+ // Display product price
+ NumberFormat currencyFormat = NumberFormat.getNumberInstance(new Locale("vi", "VN"));
+ tvProductPrice.setText(currencyFormat.format(product.getPrice()) + " đ");
+ }
+
+ private void validateAndSubmitReview() {
+ // Validate rating
+ float rating = ratingBar.getRating();
+ if (rating == 0) {
+ Toast.makeText(this, "Vui lòng đánh giá sao cho sản phẩm", Toast.LENGTH_SHORT).show();
+ return;
+ }
+
+ // Validate comment
+ String comment = etComment.getText().toString().trim();
+ if (TextUtils.isEmpty(comment)) {
+ Toast.makeText(this, "Vui lòng nhập nhận xét về sản phẩm", Toast.LENGTH_SHORT).show();
+ return;
+ }
+
+ // Create review object
+ Review review = new Review(
+ currentUser.getUid(),
+ currentUser.getEmail(),
+ currentUser.getDisplayName(),
+ productId,
+ product.getName(),
+ product.getImageUrl(),
+ comment,
+ rating,
+ orderId
+ );
+
+ // Show progress dialog
+ showProgressDialog();
+
+ // Submit review
+ reviewRepository.createReview(review, new ReviewRepository.ReviewCallback() {
+ @Override
+ public void onSuccess(Review createdReview) {
+ hideProgressDialog();
+ showSuccessDialog();
+ }
+
+ @Override
+ public void onError(String errorMessage) {
+ hideProgressDialog();
+ Toast.makeText(ProductReviewActivity.this,
+ "Lỗi khi gửi đánh giá: " + errorMessage, Toast.LENGTH_SHORT).show();
+ }
+ });
+ }
+
+ private void showProgressDialog() {
+ AlertDialog.Builder builder = new AlertDialog.Builder(this);
+ builder.setCancelable(false);
+ builder.setView(R.layout.progress_dialog);
+ progressDialog = builder.create();
+ progressDialog.show();
+ }
+
+ private void hideProgressDialog() {
+ if (progressDialog != null && progressDialog.isShowing()) {
+ progressDialog.dismiss();
+ }
+ }
+
+ private void showSuccessDialog() {
+ new AlertDialog.Builder(this)
+ .setTitle("Thành công")
+ .setMessage("Cảm ơn bạn đã đánh giá sản phẩm!")
+ .setPositiveButton("OK", (dialog, which) -> {
+ finish();
+ })
+ .setCancelable(false)
+ .show();
+ }
+}
