+
+ builder.setItems(productNames, (dialog, which) -> {
+ String selectedProductId = productIds[which];
+ showReviewScreen(selectedProductId, order.getId());
+ });
+
+ builder.setNegativeButton("Hủy", (dialog, which) -> dialog.dismiss());
+ builder.show();
+ }
