ent intent = new Intent(context, HomeMainActivity.class);\n intent.setFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_SINGLE_TOP);\n context.startActivity(intent);\n });\n\n // Configurar el botón para ir a la revisión de productos\n Button btnReviewProducts = findViewById(R.id.btnReviewProducts);\n btnReviewProducts.setOnClickListener(v -> {\n dismiss();\n Intent intent = new Intent(context, OrderDetailActivity.class);\n intent.putExtra(\"ORDER_ID\", orderId);\n intent.putExtra(\"SHOW_REVIEW\", true);\n context.startActivity(intent);\n });\n\n // Hacer que el diálogo ocupe la mayor parte del ancho de la pantalla\n Window window = getWindow();\n if (window != null) {\n window.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);\n }\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_012MpG35JtQKE7724x9M3V4T","content":"The apply model made the following changes to the file:

